create table public.novedades_posts (id uuid primary key default gen_random_uuid(), slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), status text not null default 'draft' check(status in ('draft','published')), sort_order integer not null default 0, data jsonb not null check(jsonb_typeof(data)='object'), created_at timestamptz not null default now());
create table public.novedades_page (id text primary key check(id='main'), data jsonb not null check(jsonb_typeof(data)='object'));
alter table public.novedades_posts enable row level security;
revoke all on public.novedades_posts from anon, authenticated;
grant select on public.novedades_posts to anon;
grant select,insert,update,delete on public.novedades_posts to authenticated;
create policy "public_read" on public.novedades_posts for select to anon,authenticated using (status='published');
create policy "admin_manage" on public.novedades_posts for all to authenticated using ((select public.is_admin_user())) with check ((select public.is_admin_user()));
alter table public.novedades_page enable row level security;
revoke all on public.novedades_page from anon, authenticated;
grant select on public.novedades_page to anon;
grant select,insert,update,delete on public.novedades_page to authenticated;
create policy "public_read" on public.novedades_page for select to anon,authenticated using (true);
create policy "admin_manage" on public.novedades_page for all to authenticated using ((select public.is_admin_user())) with check ((select public.is_admin_user()));
insert into public.novedades_posts(slug,status,sort_order,data) values ('alcanzar-rango-diamante-6-meses','published',0,'{"slug":"alcanzar-rango-diamante-6-meses","type":"article","category":"Estrategia","title":"Cómo alcanzar el rango Diamante en 6 meses","excerpt":"Sistema comprobado para escalar rangos rápidamente sin saturar tu red.","author":"Carlos Mendoza","authorRole":"Líder Diamante","authorAvatar":"https://images.pexels.com/photos/220453/pexels-photo-220453.jpeg?auto=compress&cs=tinysrgb&w=100","date":"15 Jun 2025","readTime":"8 min","views":4280,"image":"https://images.pexels.com/photos/3184291/pexels-photo-3184291.jpeg?auto=compress&cs=tinysrgb&w=800","featured":true,"content":"<p>Alcanzar el rango Diamante no es cuestión de suerte, sino de sistema. En este artículo te comparto el método exacto que usé para llegar ahí en 6 meses.</p><h2>1. Define tu meta mensual</h2><p>Desglosa el volumen requerido en metas semanales. Si necesitas S/ 50,000 en volumen, son S/ 12,500 por semana. Esto hace que la meta sea manejable y medible.</p><h2>2. Enfócate en retener, no solo en reclutar</h2><p>Un afiliado activo vale 10 veces más que uno nuevo. Dedica el 60% de tu tiempo a retención: llamadas de seguimiento, reconocimiento y mentoría personalizada.</p><h2>3. Duplica tu sistema</h2><p>Documenta todo lo que funciona y enséñalo a tu equipo. La duplicación es la clave del crecimiento exponencial en MLM. Si tu sistema no se puede duplicar, tu red no crecerá.</p><h2>4. Eventos semanales</h2><p>Realiza mínimo 2 presentaciones por semana. La consistencia vence al talento. Cada presentación es una oportunidad de reclutar y de motivar a tu equipo existente.</p><h2>5. Mentoría uno a uno</h2><p>Identifica a los 3 afiliados con mayor potencial y dedícales tiempo personalizado. Ellos serán tus futuros líderes y multiplicarán tu red.</p>","videoUrl":""}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('tour-completo-dashboard','published',1,'{"slug":"tour-completo-dashboard","type":"video","category":"Tutoriales","title":"Tour completo del dashboard","excerpt":"Recorrido por cada función del panel de control de Cluv360.","author":"Ana Rodríguez","authorRole":"Soporte","authorAvatar":"https://images.pexels.com/photos/415829/pexels-photo-415829.jpeg?auto=compress&cs=tinysrgb&w=100","date":"12 Jun 2025","duration":"22:15","views":6150,"image":"https://images.pexels.com/photos/3184339/pexels-photo-3184339.jpeg?auto=compress&cs=tinysrgb&w=800","featured":true,"content":"<p>En este video recorremos cada función del panel de control de Cluv360, desde el resumen general hasta los reportes avanzados.</p><h2>Resumen general</h2><p>El dashboard muestra tus comisiones, red activa, rango actual y volumen mensual de un vistazo. Todo en tiempo real.</p><h2>Comisiones</h2><p>Ve cada comisión desglosada: directas, binarias, bonos de rango y residuales. Filtra por fecha y exporta en Excel.</p><h2>Mi Red</h2><p>El árbol genealógico interactivo te permite ver, filtrar y exportar tu red completa. Usa zoom, búsqueda y filtros avanzados.</p>","videoUrl":"https://www.youtube.com/embed/dQw4w9WgXcQ"}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('comisiones-binarias-guia-2025','published',2,'{"slug":"comisiones-binarias-guia-2025","type":"article","category":"Comisiones","title":"Comisiones binarias: Guía definitiva 2025","excerpt":"Algoritmo del sistema binario explicado paso a paso.","author":"Luis García","authorRole":"Analista","authorAvatar":"https://images.pexels.com/photos/1222271/pexels-photo-1222271.jpeg?auto=compress&cs=tinysrgb&w=100","date":"10 Jun 2025","readTime":"6 min","views":3890,"image":"https://images.pexels.com/photos/3184360/pexels-photo-3184360.jpeg?auto=compress&cs=tinysrgb&w=800","content":"<p>El sistema binario de Cluv360 es uno de los más eficientes del mercado. Aquí te explico cómo funciona y cómo maximizarlo.</p><h2>¿Cómo funciona?</h2><p>Tienes dos patas: izquierda y derecha. El sistema paga un porcentaje del volumen de tu pata menor, lo que incentiva el balance.</p><h2>Balance es clave</h2><p>Mantén tus dos patas lo más balanceadas posible para maximizar comisiones. Una pata muy grande y otra pequeña significa que estás dejando dinero en la mesa.</p><h2>Límite diario</h2><p>Cada rango tiene un límite de pago diario. Conoce el tuyo para optimizar tu estrategia y no perder volumen.</p>","videoUrl":""}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('5-scripts-ventas-convierten','published',3,'{"slug":"5-scripts-ventas-convierten","type":"video","category":"Marketing","title":"5 scripts de ventas que convierten","excerpt":"Guiones probados para invitar sin presionar.","author":"María Torres","authorRole":"Coach","authorAvatar":"https://images.pexels.com/photos/774909/pexels-photo-774909.jpeg?auto=compress&cs=tinysrgb&w=100","date":"8 Jun 2025","duration":"18:30","views":5420,"image":"https://images.pexels.com/photos/3182812/pexels-photo-3182812.jpeg?auto=compress&cs=tinysrgb&w=800","content":"<p>Los scripts de ventas son herramientas, no camisas de fuerza. Aquí te comparto 5 que funcionan en el mundo real.</p><h2>1. El invitar sin presionar</h2><p>\"Tengo algo que te puede interesar, ¿tienes 10 minutos esta semana?\" — simple, directo y sin presión.</p><h2>2. El de la curiosidad</h2><p>\"Descubrí algo que está cambiando mi vida financiera, ¿quieres que te cuente?\" — genera interés sin revelar demasiado.</p><h2>3. El del problema</h2><p>\"¿Qué es lo que más te gustaría cambiar de tu situación actual?\" — abre una conversación real sobre necesidades.</p>","videoUrl":"https://www.youtube.com/embed/dQw4w9WgXcQ"}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('sistema-rangos-bronce-corona','published',4,'{"slug":"sistema-rangos-bronce-corona","type":"article","category":"Rangos","title":"Sistema de rangos: del Bronce a la Corona","excerpt":"Requisitos, bonos y beneficios de cada nivel.","author":"Ana Rodríguez","authorRole":"Soporte","authorAvatar":"https://images.pexels.com/photos/415829/pexels-photo-415829.jpeg?auto=compress&cs=tinysrgb&w=100","date":"2 Jun 2025","readTime":"5 min","views":4100,"image":"https://images.pexels.com/photos/3184465/pexels-photo-3184465.jpeg?auto=compress&cs=tinysrgb&w=800","content":"<p>El sistema de rangos de Cluv360 está diseñado para recompensar el esfuerzo y el liderazgo. Cada rango desbloquea nuevos bonos y beneficios.</p><h2>Bronce</h2><p>El punto de partida. Requiere 5 afiliados activos y S/ 2,000 en volumen mensual. Desbloquea comisiones directas.</p><h2>Plata</h2><p>15 afiliados y S/ 8,000 en volumen. Desbloquea bonos de equipo y comisiones binarias.</p><h2>Oro</h2><p>50 afiliados y S/ 20,000. Acceso a bonos de liderazgo y eventos exclusivos.</p><h2>Diamante</h2><p>500+ afiliados y S/ 50,000. Bono de rango completo y acceso a mentoría personalizada del equipo Cluv360.</p>","videoUrl":""}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('nueva-funcion-comisiones-instantaneas','published',5,'{"slug":"nueva-funcion-comisiones-instantaneas","type":"news","category":"Noticias","title":"Nueva función: Comisiones instantáneas","excerpt":"Ahora tus comisiones se acreditan en menos de 60 segundos.","author":"Equipo Cluv360","authorRole":"Producto","authorAvatar":"https://images.pexels.com/photos/3184339/pexels-photo-3184339.jpeg?auto=compress&cs=tinysrgb&w=100","date":"28 May 2025","readTime":"3 min","views":8200,"image":"https://images.pexels.com/photos/7688460/pexels-photo-7688460.jpeg?auto=compress&cs=tinysrgb&w=800","featured":true,"content":"<p>A partir de hoy, las comisiones de tu red se acreditan en menos de 60 segundos. Una mejora que cambia la experiencia de cada afiliado.</p><h2>¿Qué cambió?</h2><p>Mejoramos nuestro motor de procesamiento para que cada venta se refleje en tiempo real en tu dashboard. Sin esperas, sin solicitudes manuales.</p><h2>¿A quién aplica?</h2><p>A todos los afiliados activos, sin importar su rango. La función está disponible 24/7.</p><h2>¿Qué necesitas hacer?</h2><p>Nada. La función ya está activa en tu cuenta. Solo entra a tu dashboard y verás tus comisiones actualizadas en tiempo real.</p>","videoUrl":""}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('marketing-digital-mlm','published',6,'{"slug":"marketing-digital-mlm","type":"article","category":"Marketing","title":"Marketing digital para MLM en 2025","excerpt":"Construye tu marca personal y atrae afiliados de calidad.","author":"Ana Ríos","authorRole":"Dir. Operaciones","authorAvatar":"https://images.pexels.com/photos/774909/pexels-photo-774909.jpeg?auto=compress&cs=tinysrgb&w=100","date":"1 Jun 2025","readTime":"7 min","views":2950,"image":"https://images.pexels.com/photos/3194523/pexels-photo-3194523.jpeg?auto=compress&cs=tinysrgb&w=800","content":"<p>El marketing digital es la palanca más poderosa para un afiliado moderno. Aquí te enseño cómo usarlo correctamente.</p><h2>Marca personal primero</h2><p>La gente no se une a empresas, se une a personas. Construye tu marca antes de vender. Comparte tu journey, tus valores y tu visión.</p><h2>Contenido que atrae</h2><p>Comparte tu journey, no solo resultados. La autenticidad convierte más que la perfección. Un post honesto sobre un desafío superado genera más engagement que uno de \"gané S/ 10,000\".</p><h2>Automatiza el seguimiento</h2><p>Usa herramientas de mensajería para no perder prospectos por falta de respuesta. El 80% de las ventas requieren 5+ contactos.</p>","videoUrl":""}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('tutorial-arbol-genealogico','published',7,'{"slug":"tutorial-arbol-genealogico","type":"video","category":"Tutoriales","title":"Tutorial: Árbol genealógico interactivo","excerpt":"Domina filtros, zoom, búsqueda y exportación de tu red.","author":"Carlos Torres","authorRole":"CTO","authorAvatar":"https://images.pexels.com/photos/1222271/pexels-photo-1222271.jpeg?auto=compress&cs=tinysrgb&w=100","date":"25 May 2025","duration":"15:20","views":5420,"image":"https://images.pexels.com/photos/3182812/pexels-photo-3182812.jpeg?auto=compress&cs=tinysrgb&w=800","content":"<p>El árbol genealógico es la herramienta más poderosa de Cluv360. Aquí te enseño a usarlo como un profesional.</p><h2>Vista general</h2><p>El árbol muestra tu red binaria completa, con colores por rango y estado de actividad. Puedes ver toda tu organización de un vistazo.</p><h2>Filtros</h2><p>Filtra por rango, estado, fecha de ingreso y volumen. Encuentra rápidamente a los afiliados que necesitan tu atención.</p><h2>Zoom y navegación</h2><p>Usa los controles de zoom o el scroll del mouse para navegar por toda tu red. En móvil, usa gestos de pellizco.</p><h2>Exportación</h2><p>Exporta tu árbol en PDF o Excel para análisis offline. Ideal para presentaciones y planificación estratégica.</p>","videoUrl":"https://www.youtube.com/embed/dQw4w9WgXcQ"}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('retener-afiliados-activos','published',8,'{"slug":"retener-afiliados-activos","type":"article","category":"Estrategia","title":"El arte de retener afiliados activos","excerpt":"Técnicas de seguimiento y mentoring que multiplican la retención.","author":"Gustavo Ortiz","authorRole":"CEO","authorAvatar":"https://images.pexels.com/photos/220453/pexels-photo-220453.jpeg?auto=compress&cs=tinysrgb&w=100","date":"22 May 2025","readTime":"6 min","views":3650,"image":"https://images.pexels.com/photos/3861969/pexels-photo-3861969.jpeg?auto=compress&cs=tinysrgb&w=800","content":"<p>La retención es el verdadero secreto del éxito en MLM. Aquí te enseño cómo lograrla con un sistema probado.</p><h2>Onboarding efectivo</h2><p>Los primeros 7 días son críticos. Acompaña a cada nuevo afiliado de cerca. Un buen onboarding aumenta la retención en un 300%.</p><h2>Reconocimiento constante</h2><p>Celebra los logros pequeños. El reconocimiento es el combustible del MLM. Un mensaje de felicitación puede marcar la diferencia.</p><h2>Sistema de mentoría</h2><p>Asigna un mentor a cada nuevo afiliado. La conexión humana retiene más que el dinero. Los afiliados con mentor tienen 5x más probabilidades de permanecer activos.</p>","videoUrl":""}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('nuevas-pasarelas-pago-peru','published',9,'{"slug":"nuevas-pasarelas-pago-peru","type":"news","category":"Noticias","title":"Integramos Yape y Plin como pasarelas de pago","excerpt":"Ahora puedes cobrar comisiones directamente a Yape y Plin.","author":"Equipo Cluv360","authorRole":"Producto","authorAvatar":"https://images.pexels.com/photos/3184339/pexels-photo-3184339.jpeg?auto=compress&cs=tinysrgb&w=100","date":"18 May 2025","readTime":"2 min","views":7100,"image":"https://images.pexels.com/photos/4968391/pexels-photo-4968391.jpeg?auto=compress&cs=tinysrgb&w=800","content":"<p>Ahora puedes recibir tus comisiones directamente en Yape y Plin, las pasarelas de pago más usadas en Perú.</p><h2>¿Qué significa?</h2><p>Tus comisiones se acreditan instantáneamente en tu cuenta de Yape o Plin, sin esperas ni trámites adicionales.</p><h2>¿Cómo activarlo?</h2><p>Ve a Configuración > Métodos de pago y selecciona tu pasarela preferida. Solo necesitas tu número de celular registrado.</p><h2>Disponibilidad</h2><p>Disponible para todos los afiliados en Perú desde hoy. Próximamente en Colombia y Ecuador.</p>","videoUrl":""}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('maximizar-comisiones-binarias','published',10,'{"slug":"maximizar-comisiones-binarias","type":"video","category":"Comisiones","title":"Maximiza tus comisiones binarias","excerpt":"Aprende a optimizar el balance de tu red binaria.","author":"Carlos Torres","authorRole":"CTO","authorAvatar":"https://images.pexels.com/photos/1222271/pexels-photo-1222271.jpeg?auto=compress&cs=tinysrgb&w=100","date":"15 May 2025","duration":"8:30","views":2180,"image":"https://images.pexels.com/photos/7688460/pexels-photo-7688460.jpeg?auto=compress&cs=tinysrgb&w=800","content":"<p>Aprende a optimizar el balance de tu red binaria para maximizar comisiones con estrategias prácticas.</p><h2>La regla del 60/40</h2><p>Mantén tu pata mayor al 60% y la menor al 40% para optimizar el pago. Esto evita que el volumen se quede sin cobrar.</p><h2>Monitoreo semanal</h2><p>Revisa el balance de tus patas cada semana y ajusta tu estrategia de reclutamiento. Un afiliado nuevo en la pata menor puede marcar la diferencia.</p>","videoUrl":"https://www.youtube.com/embed/dQw4w9WgXcQ"}'::jsonb);
insert into public.novedades_posts(slug,status,sort_order,data) values ('estrategias-duplicar-red-90-dias','published',11,'{"slug":"estrategias-duplicar-red-90-dias","type":"video","category":"Estrategia","title":"Estrategias para duplicar tu red en 90 días","excerpt":"5 estrategias que los líderes Diamante usan para crecer rápido.","author":"Gustavo Ortiz","authorRole":"CEO","authorAvatar":"https://images.pexels.com/photos/220453/pexels-photo-220453.jpeg?auto=compress&cs=tinysrgb&w=100","date":"10 May 2025","duration":"12:45","views":3420,"image":"https://images.pexels.com/photos/3184291/pexels-photo-3184291.jpeg?auto=compress&cs=tinysrgb&w=800","content":"<p>Las 5 estrategias más efectivas que nuestros afiliados Diamante han utilizado para duplicar sus redes en menos de 3 meses.</p><h2>1. Seguimiento sistemático</h2><p>Tener un sistema de seguimiento automatizado más el toque personal marca la diferencia. Cada prospecto recibe mínimo 5 contactos.</p><h2>2. Eventos semanales</h2><p>Los líderes Diamante realizan mínimo 2 presentaciones semanales. La consistencia es la clave del crecimiento.</p><h2>3. Mentoría uno a uno</h2><p>Dedicar tiempo a los afiliados con mayor potencial multiplica resultados. Invierte en quienes invierten en sí mismos.</p><h2>4. Redes sociales inteligentes</h2><p>Comparte tu historia, no solo el producto. La autenticidad atrae afiliados de calidad.</p><h2>5. Duplicación de procesos</h2><p>Documenta todo lo que funcione y enséñalo a tu equipo. La duplicación es el motor del crecimiento exponencial.</p>","videoUrl":"https://www.youtube.com/embed/dQw4w9WgXcQ"}'::jsonb);
insert into public.novedades_page values ('main','{"badge":"Recursos Cluv360","title":"Novedades, guías y","highlight":"tutoriales","subtitle":"Aprende a escalar tu red, domina el sistema de comisiones y mantente al día con las novedades de la plataforma."}'::jsonb);